function describe(node, depth) {
  if (!node) return null;
  const info = {
    id: node.id,
    name: node.name,
    type: node.type,
    x: node.x, y: node.y, width: node.width, height: node.height,
  };
  if ('fills' in node && node.fills && node.fills !== figma.mixed) {
    info.fills = node.fills.map(f => f.type === 'SOLID' ? { type: f.type, color: f.color, opacity: f.opacity } : { type: f.type });
  }
  if ('strokes' in node && node.strokes) {
    info.strokes = node.strokes.map(s => s.type === 'SOLID' ? { type: s.type, color: s.color } : { type: s.type });
  }
  if ('cornerRadius' in node) info.cornerRadius = node.cornerRadius;
  if ('effects' in node && node.effects) info.effects = node.effects;
  if (node.type === 'TEXT') {
    info.characters = node.characters;
    info.fontName = node.fontName;
    info.fontSize = node.fontSize;
    info.textAlignHorizontal = node.textAlignHorizontal;
    if (node.fills && node.fills !== figma.mixed) info.textColor = node.fills;
  }
  if ('layoutMode' in node) {
    info.layoutMode = node.layoutMode;
    info.itemSpacing = node.itemSpacing;
    info.paddingLeft = node.paddingLeft;
    info.paddingTop = node.paddingTop;
  }
  if (depth > 0 && 'children' in node) {
    info.children = node.children.map(c => describe(c, depth - 1));
  }
  return info;
}

