function text(parent, opts){
  const {x=0,y=0,width,text:str,family='Nunito',style='Regular',size=15,color=C.textPrimary,align='LEFT',lineHeight,letterSpacing,name,opacity=1} = opts;
  const t = figma.createText();
  t.fontName = {family,style};
  t.characters = str;
  t.fontSize = size;
  t.fills = [SOLID(color,opacity)];
  t.textAlignHorizontal = align;
  parent.appendChild(t);
  if (lineHeight) t.lineHeight = {unit:'PIXELS', value: lineHeight};
  if (letterSpacing!==undefined) t.letterSpacing = {unit:'PIXELS', value: letterSpacing};
  if (width) { t.resize(width, t.height); t.textAutoResize='HEIGHT'; } else { t.textAutoResize='WIDTH_AND_HEIGHT'; }
  t.x = x; t.y = y;
  t.name = name || str.slice(0,30);
  return t;
}
function rect(parent, opts){
  const {x=0,y=0,width,height,fill,radius=0,name='Rect',stroke,strokeWeight=1} = opts;
  const r = figma.createRectangle();
  r.resize(width,height);
  if (fill) r.fills=[SOLID(fill)]; else r.fills=[];
  r.cornerRadius = radius;
  if (stroke) { r.strokes=[SOLID(stroke)]; r.strokeWeight=strokeWeight; }
  r.name = name;
  parent.appendChild(r);
  r.x=x; r.y=y;
  return r;
}
function frame(parent, opts){
  const {x=0,y=0,width,height,fill,radius=0,name='Frame',clip=false,stroke,strokeWeight=1,effects} = opts;
  const f = figma.createFrame();
  if(width&&height) f.resize(width,height);
  f.fills = fill? [SOLID(fill)] : [];
  f.cornerRadius=radius;
  f.clipsContent = !!clip;
  if (stroke){ f.strokes=[SOLID(stroke)]; f.strokeWeight=strokeWeight; }
  if (effects) f.effects = effects;
  f.name = name;
  if(parent) parent.appendChild(f);
  f.x=x; f.y=y;
  return f;
}
async function icon(parent, id, opts){
  const {x=0,y=0,size=24,name} = opts;
  const node = await figma.getNodeByIdAsync(id);
  const inst = node.createInstance();
  parent.appendChild(inst);
  inst.resize(size,size);
  inst.x=x; inst.y=y;
  if (name) inst.name=name;
  return inst;
}
function recolor(inst, color){
  function walk(n){
    if ('fills' in n && Array.isArray(n.fills) && n.fills.length && n.fills[0] && n.fills[0].type==='SOLID'){ n.fills = [SOLID(color)]; }
    if ('children' in n) n.children.forEach(walk);
