  function walk(n){
    if ('fills' in n && Array.isArray(n.fills) && n.fills.length){
      n.fills = n.fills.map(f=> f.type==='SOLID' ? {...f, color} : f);
    }
    if ('children' in n) n.children.forEach(walk);
  }
  walk(inst);
}
