// chart area
const chartArea = figma.createFrame();
chartArea.name='Chart';
chartArea.resize(302,110);
chartArea.x=20; chartArea.y=58;
chartArea.fills=[];
card.appendChild(chartArea);

// days Mon..Sun, values - high, medium, low, peak(highest), low, lower, lowest
// invert: stress level, higher stress = higher point then peak on thu top. we want line chart showing stress trend
const days=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];
const levels=[0.7,0.5,0.3,0.95,0.3,0.2,0.1]; // normalized stress 0-1, thu peak
const w=302, h=90;
const stepX = w/(days.length-1);
const points = levels.map((lv,i)=>({x:i*stepX, y:h-(lv*h)}));

// draw line via vector using strokes between points - use a single vector with path
let pathData = `M ${points[0].x} ${points[0].y}`;
for(let i=1;i<points.length;i++){ pathData += ` L ${points[i].x} ${points[i].y}`; }
const vector = figma.createVector();
vector.vectorPaths=[{windingRule:'NONE', data:pathData}];
vector.strokes=[{type:'SOLID', color:{r:0.533,g:0.812,b:0.651}}];
vector.strokeWeight=3;
vector.resize(w,h);
vector.x=0; vector.y=0;
chartArea.appendChild(vector);

// dots + labels
for(let i=0;i<points.length;i++){
  const dot = figma.createEllipse();
  const isPeak = i===3;
  dot.resize(isPeak?10:6, isPeak?10:6);
  dot.x = points[i].x-(isPeak?5:3);
  dot.y = points[i].y-(isPeak?5:3);
  dot.fills=[{type:'SOLID', color: isPeak? {r:0.95,g:0.45,b:0.4} : {r:0.533,g:0.812,b:0.651}}];
  chartArea.appendChild(dot);

  const dayLabel = figma.createText();
  dayLabel.fontName={family:'Nunito',style:'Regular'};
  dayLabel.characters=days[i];
  dayLabel.fontSize=11;
  dayLabel.textAlignHorizontal='CENTER';
  dayLabel.resize(30,14);
  dayLabel.x = points[i].x-15;
  dayLabel.y = h+6;
  dayLabel.fills=[{type:'SOLID', color:{r:0.55,g:0.59,b:0.56}}];
  chartArea.appendChild(dayLabel);
}

