  deltaWrap.primaryAxisSizingMode='AUTO';
  deltaWrap.counterAxisSizingMode='AUTO';
  deltaWrap.itemSpacing=4;
  deltaWrap.counterAxisAlignItems='CENTER';
  deltaWrap.fills=[];
  row.appendChild(deltaWrap);

  const deltaIcon = (async()=>{})();
  return {row, deltaWrap, delta};
}

