async function segItem(iconId, label, selected){
  const item = figma.createFrame();
  item.layoutMode='HORIZONTAL';
  item.primaryAxisAlignItems='CENTER';
  item.counterAxisAlignItems='CENTER';
  item.itemSpacing=6;
  item.paddingLeft=10; item.paddingRight=10; item.paddingTop=8; item.paddingBottom=8;
  item.cornerRadius=10;
  item.layoutGrow=1;
  item.fills = selected? [{type:'SOLID', color:{r:1,g:1,b:1}}] : [];
  if (selected) item.effects=[{type:'DROP_SHADOW', color:{r:0,g:0,b:0,a:0.08}, offset:{x:0,y:1}, radius:3, visible:true, blendMode:'NORMAL'}];
  const icon = (await figma.getNodeByIdAsync(iconId)).createInstance();
  icon.resize(16,16);
  item.appendChild(icon);
  const t = figma.createText();
  t.fontName={family:'Nunito', style:'Bold'};
  t.fontSize=13;
  t.characters=label;
  t.resize(t.width,16);
  t.fills = selected? [{type:'SOLID', color:{r:0.11,g:0.15,b:0.13}}] : [{type:'SOLID', color:{r:0.45,g:0.48,b:0.46}}];
  item.appendChild(t);
  return item;
}

