async function reminderRow(iconId, title, time, on, y){
  const row = figma.createFrame();
  row.name='ReminderRow_'+title;
  row.x=24; row.y=y; row.resize(342,72);
  row.cornerRadius=16;
  row.fills=[{type:'SOLID', color:{r:1,g:1,b:1}}];
  row.effects=[{type:'DROP_SHADOW', color:{r:0,g:0,b:0,a:0.05}, offset:{x:0,y:1}, radius:4, visible:true, blendMode:'NORMAL'}];
  frame.appendChild(row);

  const iconBg = figma.createFrame();
  iconBg.resize(44,44); iconBg.x=16; iconBg.y=14; iconBg.cornerRadius=12;
  iconBg.fills=[{type:'SOLID', color:{r:0.925,g:0.968,b:0.943}}];
  iconBg.layoutMode='HORIZONTAL';
  iconBg.primaryAxisAlignItems='CENTER';
  iconBg.counterAxisAlignItems='CENTER';
  row.appendChild(iconBg);
  const icon = (await figma.getNodeByIdAsync(iconId)).createInstance();
  icon.resize(20,20);
  iconBg.appendChild(icon);

  const t = figma.createText();
  t.fontName={family:'Nunito', style:'Bold'};
  t.fontSize=14;
  t.characters=title;
  t.x=72; t.y=18; t.resize(180,20);
  t.fills=[{type:'SOLID', color:{r:0.11,g:0.15,b:0.13}}];
  row.appendChild(t);

  const tm = figma.createText();
  tm.fontName={family:'Nunito', style:'Regular'};
  tm.fontSize=13;
  tm.characters=time;
  tm.x=72; tm.y=40; tm.resize(180,18);
  tm.fills=[{type:'SOLID', color:{r:0.5,g:0.54,b:0.52}}];
  row.appendChild(tm);

  // toggle
  const toggle = figma.createFrame();
  toggle.name='Toggle';
  toggle.resize(44,26); toggle.x=342-16-44; toggle.y=23; toggle.cornerRadius=13;
  toggle.fills=[{type:'SOLID', color: on? {r:0.533,g:0.812,b:0.651} : {r:0.88,g:0.89,b:0.885}}];
  row.appendChild(toggle);
  const knob = figma.createEllipse();
  knob.resize(22,22);
  knob.x = on? 20 : 2;
  knob.y=2;
  knob.fills=[{type:'SOLID', color:{r:1,g:1,b:1}}];
  toggle.appendChild(knob);

  return row;
}

