function describe(n, depth){
  const o = {id:n.id, name:n.name, type:n.type, x:n.x, y:n.y};
  if (n.type==='TEXT') o.characters = n.characters;
  if ('children' in n && depth<2) o.children = n.children.map(c=>describe(c, depth+1));
