async function makeTile(x, y, iconId, title, subtitle, name){
  const tile = figma.createFrame();
  tile.name=name;
  tile.resize(165,120);
  tile.x=x; tile.y=y;
  tile.cornerRadius=16;
  tile.fills=[{type:'SOLID', color:{r:1,g:1,b:1}}];
  tile.effects=[{type:'DROP_SHADOW', color:{r:0,g:0,b:0,a:0.05}, offset:{x:0,y:2}, radius:8, visible:true, blendMode:'NORMAL'}];
  frame.appendChild(tile);

  const iconBg = figma.createFrame();
  iconBg.resize(40,40);
  iconBg.x=16; iconBg.y=16;
  iconBg.cornerRadius=20;
  iconBg.fills=[{type:'SOLID', color:{r:0.949,g:0.6,b:0.42}, opacity:0.18}];
  tile.appendChild(iconBg);
  const iconSym = await figma.getNodeByIdAsync(iconId);
  const icon = iconSym.createInstance();
  icon.resize(20,20);
  icon.x=10; icon.y=10;
  icon.fills=[{type:'SOLID', color:{r:0.8,g:0.4,b:0.25}}];
  iconBg.appendChild(icon);

  const t1 = figma.createText();
  t1.fontName={family:'Nunito',style:'Bold'};
  t1.fontSize=14;
  t1.characters=title;
  t1.fills=[{type:'SOLID', color:{r:0.11,g:0.16,b:0.14}}];
  t1.x=16; t1.y=66;
  t1.resize(133,18);
  tile.appendChild(t1);

  const t2 = figma.createText();
  t2.fontName={family:'Nunito',style:'Regular'};
  t2.fontSize=12;
  t2.characters=subtitle;
  t2.fills=[{type:'SOLID', color:{r:0.4,g:0.45,b:0.43}}];
  t2.x=16; t2.y=86;
  t2.resize(133,28);
  tile.appendChild(t2);
  return tile;
}

